#!/bin/bash
set -e

echo "=================================================="
echo " Deploy: Follow-up date picker (calendar instead"
echo " of relative-period dropdown)"
echo "=================================================="
echo ""
echo "Doctor module -> Follow-up card: the \"After\" dropdown"
echo "(1 week / 2 weeks / 1 month / ...) is replaced with an"
echo "actual calendar date picker. Added an \"SOS / As Needed\""
echo "checkbox for the old SOS case, which isn't a real date."
echo ""
echo "DATABASE: this script already assumes the migration"
echo "below has been applied -- it WAS applied directly to"
echo "both Supabase projects already:"
echo "  - plan_followups.followup_date (new, nullable date)"
echo "  - plan_followups.after_period  (now nullable, kept"
echo "    for old records and as the SOS marker)"
echo "No action needed from you on the DB side."
echo ""

TARGET="app/consultation/[id]/consultation-form.js"
if [ ! -f "$TARGET" ]; then
  echo "ERROR: $TARGET not found. Run this script from the repo root."
  exit 1
fi
echo "Backing up $TARGET ..."
cp "$TARGET" "$TARGET.bak"
echo "Writing updated $TARGET ..."
echo "" | base64 -d > "$TARGET"
node --check "$TARGET" && echo "  Syntax OK: $TARGET"

TARGET="app/(main)/consultation/actions.js"
if [ ! -f "$TARGET" ]; then
  echo "ERROR: $TARGET not found. Run this script from the repo root."
  exit 1
fi
echo "Backing up $TARGET ..."
cp "$TARGET" "$TARGET.bak"
echo "Writing updated $TARGET ..."
echo "" | base64 -d > "$TARGET"
node --check "$TARGET" && echo "  Syntax OK: $TARGET"

TARGET="app/print-templates/actions.js"
if [ ! -f "$TARGET" ]; then
  echo "ERROR: $TARGET not found. Run this script from the repo root."
  exit 1
fi
echo "Backing up $TARGET ..."
cp "$TARGET" "$TARGET.bak"
echo "Writing updated $TARGET ..."
echo "" | base64 -d > "$TARGET"
node --check "$TARGET" && echo "  Syntax OK: $TARGET"

TARGET="app/visit-summary-print/[encounterId]/page.js"
if [ ! -f "$TARGET" ]; then
  echo "ERROR: $TARGET not found. Run this script from the repo root."
  exit 1
fi
echo "Backing up $TARGET ..."
cp "$TARGET" "$TARGET.bak"
echo "Writing updated $TARGET ..."
echo "" | base64 -d > "$TARGET"
node --check "$TARGET" && echo "  Syntax OK: $TARGET"

echo ""
echo "Done. Review the diff with:"
echo '  git diff "app/consultation/[id]/consultation-form.js" "app/(main)/consultation/actions.js" app/print-templates/actions.js "app/visit-summary-print/[encounterId]/page.js"'
echo ""
echo "Print templates (OPD Case Sheet, Visit Summary) now show"
echo "the actual date when set, falling back to the old period"
echo "text or \"SOS / As Needed\" for legacy records."
